def select_neighbor(archive: List[Tuple[np.ndarray, Tuple[float, float]]], weight_lst: np.ndarray, value1_lst: np.ndarray, value2_lst: np.ndarray, capacity: float) -> np.ndarray:
    """
    Select a promising solution from the archive and generate a neighbor solution from it.

    Args:
    archive: List of (solution, objective) pairs. Each solution is a binary numpy array (0/1) of item selections.
             Each objective is a tuple of two float values (total value1, total value2).
    weight_lst: Numpy array of shape (N, ), item weights.
    value1_lst: Numpy array of shape (N, ), item values for objective 1.
    value2_lst: Numpy array of shape (N, ), item values for objective 2.
    capacity: Maximum allowed total weight.

    Returns:
    A new neighbor solution (numpy array).
    """
    if not archive:
        raise ValueError("Archive is empty.")

    solutions = [sol for sol, _ in archive]
    objectives = np.array([obj for _, obj in archive])

    if len(solutions) > 1:
        crowding_distances = np.zeros(len(solutions))
        for i in range(2):
            sorted_idx = np.argsort(objectives[:, i])
            crowding_distances[sorted_idx[0]] = np.inf
            crowding_distances[sorted_idx[-1]] = np.inf
            for j in range(1, len(solutions)-1):
                crowding_distances[sorted_idx[j]] += (objectives[sorted_idx[j+1], i] - objectives[sorted_idx[j-1], i]) / (objectives[sorted_idx[-1], i] - objectives[sorted_idx[0], i] + 1e-8)
        selected_idx = np.argmax(crowding_distances)
    else:
        selected_idx = 0

    base_solution = solutions[selected_idx].copy()
    new_solution = base_solution.copy()

    value_weight_ratio = (value1_lst + value2_lst) / (weight_lst + 1e-8)
    sorted_items = np.argsort(-value_weight_ratio)

    for _ in range(3):
        if random.random() < 0.7:
            group_size = random.randint(1, min(3, len(sorted_items)))
            group = sorted_items[:group_size]
            if random.random() < 0.5:
                for item in group:
                    if new_solution[item] == 0 and np.sum(weight_lst[new_solution == 1]) + weight_lst[item] <= capacity:
                        new_solution[item] = 1
            else:
                for item in group:
                    if new_solution[item] == 1:
                        new_solution[item] = 0

        if random.random() < 0.4:
            perturbation_size = random.randint(1, min(2, len(sorted_items)))
            for item in sorted_items[:perturbation_size]:
                if new_solution[item] == 1:
                    new_solution[item] = 0
                else:
                    if np.sum(weight_lst[new_solution == 1]) + weight_lst[item] <= capacity:
                        new_solution[item] = 1

    return new_solution

